import pandas as pd
import numpy as np
from statsmodels.tsa.filters.hp_filter import hpfilter

def get_nominal_data(file_path):
    df = pd.read_excel(file_path, engine='xlrd', header=None)
    data = {}

    q_vals = []
    found_2024_q1 = False

    for i in range(len(df)):
        val0 = str(df.iloc[i, 0]).strip()

        # Annual data: "1973."
        if val0.endswith('.') and val0[:-1].isdigit():
            year = int(val0[:-1])
            if 1973 <= year <= 2023:
                try:
                    data[year] = float(df.iloc[i, 1])
                except (ValueError, TypeError):
                    pass

        # 2024 Quarters
        if '2024: I.' in val0:
            try:
                q_vals.append(float(df.iloc[i, 1]))
                found_2024_q1 = True
            except (ValueError, TypeError):
                pass
        elif found_2024_q1:
            if val0 == 'II.':
                try:
                    q_vals.append(float(df.iloc[i, 1]))
                except (ValueError, TypeError):
                    pass
            elif val0 == 'III p.' or val0 == 'III.':
                try:
                    q_vals.append(float(df.iloc[i, 1]))
                except (ValueError, TypeError):
                    pass
                found_2024_q1 = False # Stop looking after Q3
            elif val0 == 'IV.':
                try:
                    q_vals.append(float(df.iloc[i, 1]))
                except (ValueError, TypeError):
                    pass
                found_2024_q1 = False

    if q_vals:
        data[2024] = np.mean(q_vals)

    return data

# Extract PCE
pce_nominal = get_nominal_data('ERP-2025-table10.xls')
# Extract PFI
pfi_nominal = get_nominal_data('ERP-2025-table12.xls')

# Load CPI
df_cpi = pd.read_excel('CPI.xlsx', engine='openpyxl')
cpi_data = df_cpi.set_index('Year')['CPI_2024'].to_dict()

# Merge and calculate real values
years = sorted(pce_nominal.keys())
records = []
for y in years:
    if y in pce_nominal and y in pfi_nominal and y in cpi_data:
        real_pce = pce_nominal[y] / cpi_data[y]
        real_pfi = pfi_nominal[y] / cpi_data[y]
        records.append({
            'year': y,
            'real_pce': real_pce,
            'real_pfi': real_pfi
        })

df = pd.DataFrame(records)

# Log transformation
df['log_pce'] = np.log(df['real_pce'])
df['log_pfi'] = np.log(df['real_pfi'])

# HP Filter (lambda = 100 for annual data)
cycle_pce, trend_pce = hpfilter(df['log_pce'], lamb=100)
cycle_pfi, trend_pfi = hpfilter(df['log_pfi'], lamb=100)

# Pearson Correlation
correlation = np.corrcoef(cycle_pce, cycle_pfi)[0, 1]

# Output result
result = f"{correlation:.5f}"
print(f"Correlation: {result}")
print(f"Data years: {df['year'].min()} to {df['year'].max()} (Total: {len(df)})")

with open('answer.txt', 'w') as f:
    f.write(result)

